export class CustodyListPage {
  private http = inject(HttpClient);
  private toast = inject(ToastService);
  private auth = inject(AuthService);

  readonly tableKey = 'list.component';

  readonly columns = [
    { field: 'agent', searchField: 'agent', header: 'custody.list.col_agent', sortable: true },
    { field: 'amount', header: 'custody.list.col_amount', sortable: true },
    { field: 'transferred_in', header: 'custody.list.col_transferred_in', sortable: true },
    { field: 'spent', header: 'custody.list.col_spent', sortable: true },
    { field: 'remaining', header: 'custody.list.col_remaining', sortable: true },
    { field: 'spent_percent', header: 'custody.list.col_spent_percent', sortable: true },
    { field: 'status', header: 'custody.list.col_status', sortable: true },
    { field: 'actions', header: 'common.actions', sortable: false },
  ];

  /** status tabs — the exact values CustodyController@index filters on */
  readonly statusTabs = [
    { value: 'all' },
    { value: 'pending' },
    { value: 'accepted' },
    { value: 'active' },
    { value: 'partially_returned' },
    { value: 'closed' },
    { value: 'cancelled' },
    { value: 'rejected' },
  ];

  /** Blade actions.blade.php shows the return modal for the agent's own accepted custody */
  readonly openStates = ['accepted', 'active', 'partially_returned'];

  params = signal<CustodyListParams>({ page: 1, per_page: 25, q: '', status: 'all' });

  data = resource<ListResponse<Row>, unknown>({
    loader: () =>
      firstValueFrom(this.http.get<ListResponse<Row>>('/custodies', { params: cleanParams(this.params()) })),
  });

  canCreate = computed(() => this.auth.can('may_create_custody'));
  canApprove = computed(() => this.auth.can('may_approve_custody'));
  isAgent = computed(() => this.auth.can('is_agent') || this.auth.hasRole('مندوب'));
  /** Blade: accountants and managers get the office variants of the create buttons */
  isOffice = computed(() => this.auth.can('is_accountant') || this.auth.can('is_manager'));

  active = signal<Row | null>(null);
  sending = signal(false);
  actionError = signal<HttpErrorResponse | null>(null);

  private reason = viewChild.required(ReasonDialogComponent);

  summaryValue(key: string): string {
    const value = this.data.value()?.meta?.summary?.[key];
    return value === undefined || value === null ? '0' : String(value);
  }

  setParam(key: string, value: string): void {
    this.params.update((p) => ({ ...p, [key]: value, page: 1 }));
    this.data.reload();
  }

  onSearch(term: string): void { this.setParam('q', term); }

  openReject(row: Row): void {
    this.active.set(row);
    this.actionError.set(null);
    this.reason().open();
  }

  submitReject(reason: string): void {
    const row = this.active();
    if (row === null) {
      return;
    }
    this.sending.set(true);
    this.actionError.set(null);
    void firstValueFrom(this.http.post<ActionResponse>(`/custodies/${row.id}/reject`, { reason }))
      .then((res) => {
        this.sending.set(false);
        this.reason().done();
        this.toast.success(res.message);
        this.data.reload();
      })
      .catch((err: unknown) => {
        this.sending.set(false);
        const response = err instanceof HttpErrorResponse ? err : null;
        this.actionError.set(response);
        if (response) {
          this.toast.apiError(response.error?.message ?? 'errors.generic', response.error?.code);
        }
      });
  }

  onPage(event: { page: number; per_page: number; sort?: string }): void {
    const current = this.params();
    const sort = event.sort ?? '';
    if (current.page === event.page && current.per_page === event.per_page && current.sort === sort) {
      return;
    }
    this.params.update((p) => ({ ...p, page: event.page, per_page: event.per_page, sort }));
    this.data.reload();
  }
}

function cleanParams(params: object): Record<string, string> {
  const result: Record<string, string> = {};
  for (const [key, value] of Object.entries(params)) {
    if (value !== null && value !== undefined && value !== '' && value !== 'all') {
      result[key] = String(value);
    }
  }
  return result;
}
